using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Variante direccional de la skill de vapor industrial.
/// Hereda de IndustrialFogCar pero ignora su punto único de spawn.
/// - Define dos empties: forwardSpawn y backwardSpawn.
/// - En OnProbabilitySuccess detecta hornos (Furnace / HeatSphere) cercanos.
/// - Si los hornos más cercanos están mayormente detrás del coche => instancia atrás; si no => adelante.
/// - Instancia un prefab grande de vapor (steamPrefab).
/// - El prefab debe incluir un collider (trigger) con el script SteamHeatDisabler para afectar hornos.
/// </summary>
public class IndustrialDirectionalSteamCar : IndustrialFogCar
{
    [Header("Directional Steam Settings")] 
    [Tooltip("Spawn point delantero.")] [SerializeField] private Transform forwardSpawn;
    [Tooltip("Spawn point trasero.")] [SerializeField] private Transform backwardSpawn;
    [Tooltip("Prefab del gran vapor direccional.")] [SerializeField] private GameObject steamPrefab;
    [Tooltip("Radio de búsqueda para localizar hornos / fuentes de calor.")] [SerializeField] private float furnaceSearchRadius = 25f;
    [Tooltip("Capas consideradas para la búsqueda de hornos.")] [SerializeField] private LayerMask furnaceLayerMask;
    [Tooltip("Cuántos colliders máximos evaluar por barrido.")] [SerializeField] private int maxFurnaceColliders = 32;
    [Tooltip("Mantener el vapor parentado al spawn elegido.")] [SerializeField] private bool parentSteam = true;
    [Tooltip("Destruir automáticamente el vapor tras esta duración (0 = infinito hasta que el prefab se auto-destruya)." )]
    [SerializeField] private float autoDestroyAfter = 8f;

    [Header("Debug")] 
    [SerializeField] private bool debugLogs = false;
    [SerializeField] private Color searchGizmoColor = new Color(1f,0.8f,0.4f,0.15f);

    private readonly Collider[] _overlapResults = new Collider[64];
    private GameObject activeSteamInstance;

    protected override void OnProbabilitySuccess(Collider col, GameObject spawnedInstance)
    {
        // Ignoramos la lógica de IndustrialFogCar y aplicamos la propia direccional.
        SpawnDirectionalSteam();
    }

    private void SpawnDirectionalSteam()
    {
        if (steamPrefab == null)
        {
            if (debugLogs) Debug.LogWarning("[IndustrialDirectionalSteamCar] No hay steamPrefab asignado.", this);
            return;
        }
        if (!forwardSpawn || !backwardSpawn)
        {
            if (debugLogs) Debug.LogWarning("[IndustrialDirectionalSteamCar] Falta asignar forwardSpawn o backwardSpawn.", this);
            return;
        }

        // Buscar hornos cercanos.
        Vector3 center = transform.position;
        int count = Physics.OverlapSphereNonAlloc(center, furnaceSearchRadius, _overlapResults, furnaceLayerMask, QueryTriggerInteraction.Collide);
        if (debugLogs) Debug.Log($"[IndustrialDirectionalSteamCar] Hornos detectados: {count}", this);

        int forwardVotes = 0;
        int backwardVotes = 0;

        Vector3 fwd = transform.forward;
        for (int i = 0; i < count && i < maxFurnaceColliders; i++)
        {
            var c = _overlapResults[i];
            if (c == null) continue;
            // Considerar objeto que tenga Furnace o HeatSphere
            bool isFurnace = c.GetComponentInParent<Furnace>() != null || c.GetComponentInParent<HeatSphere>() != null;
            if (!isFurnace) continue;
            Vector3 dir = (c.transform.position - center).normalized;
            float dot = Vector3.Dot(fwd, dir); // >0 delante, <0 detrás
            if (dot >= 0f) forwardVotes++; else backwardVotes++;
        }

        // Decidir spawn
        Transform chosen = forwardSpawn;
        if (backwardVotes > forwardVotes) chosen = backwardSpawn;

        if (activeSteamInstance != null)
        {
            Destroy(activeSteamInstance);
            activeSteamInstance = null;
        }

        activeSteamInstance = Instantiate(steamPrefab, chosen.position, chosen.rotation);
        if (parentSteam && activeSteamInstance) activeSteamInstance.transform.SetParent(chosen, true);

        if (debugLogs)
        {
            Debug.Log($"[IndustrialDirectionalSteamCar] Vapor instanciado en {(chosen == forwardSpawn ? "DELANTE" : "ATRÁS")} (FwdVotes={forwardVotes} / BackVotes={backwardVotes}).", this);
        }

        if (autoDestroyAfter > 0f && activeSteamInstance != null)
        {
            Destroy(activeSteamInstance, autoDestroyAfter);
        }
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = searchGizmoColor;
        Gizmos.DrawSphere(transform.position, furnaceSearchRadius);
        if (forwardSpawn)
        {
            Gizmos.color = Color.green; Gizmos.DrawWireCube(forwardSpawn.position, Vector3.one * 0.5f);
        }
        if (backwardSpawn)
        {
            Gizmos.color = Color.red; Gizmos.DrawWireCube(backwardSpawn.position, Vector3.one * 0.5f);
        }
    }
#endif
}

using System.Collections.Generic;
using UnityEngine;
using UnityEngine.Serialization;

/// <summary>
/// Variante direccional de la skill de vapor industrial.
/// Hereda de IndustrialFogCar pero ignora su punto único de spawn.
/// - Define dos empties: forwardSpawn y backwardSpawn.
/// - En OnProbabilitySuccess detecta hornos (Furnace / HeatSphere) cercanos.
/// - Si los hornos más cercanos están mayormente detrás del coche => instancia atrás; si no => adelante.
/// - Instancia un prefab grande de vapor (steamPrefab).
/// - El prefab debe incluir un collider (trigger) con el script SteamHeatDisabler para afectar hornos.
/// </summary>
public class IndustrialDirectionalSteamCar : IndustrialFogCar
{
    [Header("Directional Steam Settings")] 
    [Tooltip("Spawn point delantero.")] [SerializeField] private Transform forwardSpawn;
    [Tooltip("Spawn point trasero.")] [SerializeField] private Transform backwardSpawn;
    [Tooltip("Prefab del gran vapor direccional.")] [SerializeField] private GameObject steamPrefab;
    [Tooltip("Radio de búsqueda para localizar hornos / fuentes de calor.")] [SerializeField] private float furnaceSearchRadius = 25f;
    [Tooltip("Capas consideradas para la búsqueda de hornos.")] [SerializeField] private LayerMask furnaceLayerMask;
    [Tooltip("Cuántos colliders máximos evaluar por barrido.")] [SerializeField] private int maxFurnaceColliders = 32;
    [Tooltip("Mantener el vapor parentado al spawn elegido.")] [SerializeField] private bool parentSteam = true;
    [Tooltip("Destruir automáticamente el vapor tras esta duración (0 = infinito hasta que el prefab se auto-destruya)." )]
    [SerializeField] private float autoDestroyAfter = 8f;

    [Header("Debug")] 
    [FormerlySerializedAs("debugLogs")]
    [SerializeField] private bool debugLogsDirectional = false;
    [SerializeField] private Color searchGizmoColor = new Color(1f,0.8f,0.4f,0.15f);

    private readonly Collider[] _overlapResults = new Collider[64];
    private GameObject activeSteamInstance;

    protected override void OnProbabilitySuccess(Collider col, GameObject spawnedInstance)
    {
        // Ignoramos la lógica de IndustrialFogCar y aplicamos la propia direccional.
        SpawnDirectionalSteam();
    }

    private void SpawnDirectionalSteam()
    {
        if (steamPrefab == null)
        {
            if (debugLogsDirectional) Debug.LogWarning("[IndustrialDirectionalSteamCar] No hay steamPrefab asignado.", this);
            return;
        }
        if (!forwardSpawn || !backwardSpawn)
        {
            if (debugLogsDirectional) Debug.LogWarning("[IndustrialDirectionalSteamCar] Falta asignar forwardSpawn o backwardSpawn.", this);
            return;
        }

        // Buscar hornos cercanos.
        Vector3 center = transform.position;
        int count = Physics.OverlapSphereNonAlloc(center, furnaceSearchRadius, _overlapResults, furnaceLayerMask, QueryTriggerInteraction.Collide);
        if (debugLogsDirectional) Debug.Log($"[IndustrialDirectionalSteamCar] Hornos detectados: {count}", this);

        int forwardVotes = 0;
        int backwardVotes = 0;

        Vector3 fwd = transform.forward;
        for (int i = 0; i < count && i < maxFurnaceColliders; i++)
        {
            var c = _overlapResults[i];
            if (c == null) continue;
            // Considerar objeto que tenga Furnace o HeatSphere
            bool isFurnace = c.GetComponentInParent<Furnace>() != null || c.GetComponentInParent<HeatSphere>() != null;
            if (!isFurnace) continue;
            Vector3 dir = (c.transform.position - center).normalized;
            float dot = Vector3.Dot(fwd, dir); // >0 delante, <0 detrás
            if (dot >= 0f) forwardVotes++; else backwardVotes++;
        }

        // Decidir spawn
        Transform chosen = forwardSpawn;
        if (backwardVotes > forwardVotes) chosen = backwardSpawn;

        if (activeSteamInstance != null)
        {
            Destroy(activeSteamInstance);
            activeSteamInstance = null;
        }

        activeSteamInstance = Instantiate(steamPrefab, chosen.position, chosen.rotation);
        if (parentSteam && activeSteamInstance) activeSteamInstance.transform.SetParent(chosen, true);

        if (debugLogsDirectional)
        {
            Debug.Log($"[IndustrialDirectionalSteamCar] Vapor instanciado en {(chosen == forwardSpawn ? "DELANTE" : "ATRÁS")} (FwdVotes={forwardVotes} / BackVotes={backwardVotes}).", this);
        }

        if (autoDestroyAfter > 0f && activeSteamInstance != null)
        {
            Destroy(activeSteamInstance, autoDestroyAfter);
        }
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        Gizmos.color = searchGizmoColor;
        Gizmos.DrawSphere(transform.position, furnaceSearchRadius);
        if (forwardSpawn)
        {
            Gizmos.color = Color.green; Gizmos.DrawWireCube(forwardSpawn.position, Vector3.one * 0.5f);
        }
        if (backwardSpawn)
        {
            Gizmos.color = Color.red; Gizmos.DrawWireCube(backwardSpawn.position, Vector3.one * 0.5f);
        }
    }
#endif
}

using UnityEngine;
using System.Collections.Generic;

/// <summary>
/// HeatSpherent
/// Coloca este script en un GameObject vacío con un SphereCollider (isTrigger = true).
/// Comportamiento:
///  - Al entrar en contacto (OnTriggerEnter) con cualquier HeatSphere:
///      * Llama CooldownOff() a TODOS los HeatSphere actualmente solapados con el volumen del SphereCollider.
///      * Se destruye (opcionalmente con un pequeño retardo para permitir efectos visuales).
///  - Si no hubiera HeatSphere en ese frame (raro), no hace nada hasta que uno entre.
/// Afecta a "todos" en un solo ciclo usando un barrido Physics.OverlapSphere para no depender de múltiples OnTriggerEnter secuenciales.
/// </summary>
[DisallowMultipleComponent]
[RequireComponent(typeof(SphereCollider))]
public class HeatSpherent : MonoBehaviour
{
    [Header("Cooldown Auto-destrucción")]
    [Tooltip("Tiempo en segundos antes de que el HeatSpherent se autodestruya.")]
    [SerializeField] private float destructionCooldown = 5f;

    [Header("Debug")] 
    [SerializeField] private bool debugLogs = false;
    [SerializeField] private Color gizmoColor = new Color(0.2f, 0.7f, 1f, 0.25f);

    private bool _consumed = false;
    private SphereCollider _sphere;
    private float _currentCooldown;
    private static readonly Collider[] _overlap = new Collider[128];

    private void Awake()
    {
        _sphere = GetComponent<SphereCollider>();
        if (_sphere != null) _sphere.isTrigger = true;
        _currentCooldown = destructionCooldown;
    }

    private void Update()
    {
        if (_currentCooldown > 0f)
        {
            _currentCooldown -= Time.deltaTime;

            if (_currentCooldown <= 0f)
            {
                if (debugLogs)
                {
                    Debug.Log($"[HeatSpherent] Cooldown alcanzado, autodestruyendo.", this);
                }
                Destroy(gameObject);
            }
        }
    }

    private void OnTriggerEnter(Collider other)
    {
        if (_consumed) return;
        if (other == null) return;

        if (other.GetComponentInParent<HeatSphere>() == null) return; // sólo reaccionar cuando realmente entra un HeatSphere

        ActivateAndConsume();
    }

    private void ActivateAndConsume()
    {
        _consumed = true;

        int affected = AffectAllOverlappingHeatSpheres();
        if (debugLogs)
        {
            Debug.Log($"[HeatSpherent] HeatSphere afectados: {affected}", this);
        }
    }

    /// <summary>
    /// Llama CooldownOff() a todos los HeatSphere que estén actualmente solapados con el volumen del SphereCollider.
    /// </summary>
    private int AffectAllOverlappingHeatSpheres()
    {
        if (_sphere == null)
        {
            if (debugLogs) Debug.LogWarning("[HeatSpherent] Sin SphereCollider.", this);
            return 0;
        }

        float effectiveRadius = _sphere.radius * Mathf.Max(transform.lossyScale.x, transform.lossyScale.y, transform.lossyScale.z);
        int count = Physics.OverlapSphereNonAlloc(transform.position + _sphere.center, effectiveRadius, _overlap, Physics.AllLayers, QueryTriggerInteraction.Collide);

        int affected = 0;
        HashSet<HeatSphere> processed = new HashSet<HeatSphere>();

        for (int i = 0; i < count; i++)
        {
            var col = _overlap[i];
            if (col == null) continue;
            var hs = col.GetComponentInParent<HeatSphere>();
            if (hs == null) continue;
            if (processed.Contains(hs)) continue; // evitar duplicados si varios colliders del mismo heat sphere

            hs.CooldownOff();
            processed.Add(hs);
            affected++;
        }

        return affected;
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        if (_sphere == null) _sphere = GetComponent<SphereCollider>();
        if (_sphere == null) return;
        Gizmos.color = gizmoColor;
        float effectiveRadius = _sphere.radius * Mathf.Max(transform.lossyScale.x, transform.lossyScale.y, transform.lossyScale.z);
        Gizmos.DrawWireSphere(transform.position + _sphere.center, effectiveRadius);
    }
#endif
}

using UnityEngine;
using System.Collections.Generic;

/// <summary>
/// HeatSpherent
/// Coloca este script en un GameObject vacío con un SphereCollider (isTrigger = true).
/// Comportamiento:
///  - Al entrar en contacto (OnTriggerEnter) con cualquier HeatSphere:
///      * Llama CooldownOff() a TODOS los HeatSphere actualmente solapados con el volumen del SphereCollider.
///      * Se destruye (opcionalmente con un pequeño retardo para permitir efectos visuales).
///  - Si no hubiera HeatSphere en ese frame (raro), no hace nada hasta que uno entre.
/// Afecta a "todos" en un solo ciclo usando un barrido Physics.OverlapSphere para no depender de múltiples OnTriggerEnter secuenciales.
/// </summary>
[DisallowMultipleComponent]
[RequireComponent(typeof(SphereCollider))]
public class HeatSpherent : MonoBehaviour
{
    [Header("Cooldown Auto-destrucción")]
    [Tooltip("Tiempo en segundos antes de que el HeatSpherent se autodestruya.")]
    [SerializeField] private float destructionCooldown = 5f;

    [Header("Debug")] 
    [SerializeField] private bool debugLogs = false;
    [SerializeField] private Color gizmoColor = new Color(0.2f, 0.7f, 1f, 0.25f);

    private bool _consumed = false;
    private SphereCollider _sphere;
    private float _currentCooldown;
    private static readonly Collider[] _overlap = new Collider[128];

    private void Awake()
    {
        _sphere = GetComponent<SphereCollider>();
        if (_sphere != null) _sphere.isTrigger = true;
        _currentCooldown = destructionCooldown;
    }

    private void Update()
    {
        // Detectar HeatSphere activamente
        if (!_consumed)
        {
            DetectAndActivate();
        }

        // Sistema de cooldown auto-destrucción
        if (_currentCooldown > 0f)
        {
            _currentCooldown -= Time.deltaTime;

            if (_currentCooldown <= 0f)
            {
                if (debugLogs)
                {
                    Debug.Log($"[HeatSpherent] Cooldown alcanzado, autodestruyendo.", this);
                }
                Destroy(gameObject);
            }
        }
    }

    private void DetectAndActivate()
    {
        if (_sphere == null) return;

        float effectiveRadius = _sphere.radius * Mathf.Max(transform.lossyScale.x, transform.lossyScale.y, transform.lossyScale.z);
        int count = Physics.OverlapSphereNonAlloc(transform.position + _sphere.center, effectiveRadius, _overlap, Physics.AllLayers, QueryTriggerInteraction.Collide);

        // Buscar si hay alguna HeatSphere en el área
        for (int i = 0; i < count; i++)
        {
            var col = _overlap[i];
            if (col == null) continue;

            var hs = col.GetComponentInParent<HeatSphere>();
            if (hs != null)
            {
                // Encontramos al menos una HeatSphere, activamos
                ActivateAndConsume();
                return;
            }
        }
    }

    private void ActivateAndConsume()
    {
        _consumed = true;

        int affected = AffectAllOverlappingHeatSpheres();
        if (debugLogs)
        {
            Debug.Log($"[HeatSpherent] HeatSphere afectados: {affected}", this);
        }
    }

    /// <summary>
    /// Llama CooldownOff() a todos los HeatSphere que estén actualmente solapados con el volumen del SphereCollider.
    /// </summary>
    private int AffectAllOverlappingHeatSpheres()
    {
        if (_sphere == null)
        {
            if (debugLogs) Debug.LogWarning("[HeatSpherent] Sin SphereCollider.", this);
            return 0;
        }

        float effectiveRadius = _sphere.radius * Mathf.Max(transform.lossyScale.x, transform.lossyScale.y, transform.lossyScale.z);
        int count = Physics.OverlapSphereNonAlloc(transform.position + _sphere.center, effectiveRadius, _overlap, Physics.AllLayers, QueryTriggerInteraction.Collide);

        int affected = 0;
        HashSet<HeatSphere> processed = new HashSet<HeatSphere>();

        for (int i = 0; i < count; i++)
        {
            var col = _overlap[i];
            if (col == null) continue;
            var hs = col.GetComponentInParent<HeatSphere>();
            if (hs == null) continue;
            if (processed.Contains(hs)) continue; // evitar duplicados si varios colliders del mismo heat sphere

            hs.CooldownOff();
            processed.Add(hs);
            affected++;
        }

        return affected;
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        if (_sphere == null) _sphere = GetComponent<SphereCollider>();
        if (_sphere == null) return;
        Gizmos.color = gizmoColor;
        float effectiveRadius = _sphere.radius * Mathf.Max(transform.lossyScale.x, transform.lossyScale.y, transform.lossyScale.z);
        Gizmos.DrawWireSphere(transform.position + _sphere.center, effectiveRadius);
    }
#endif
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Objeto genérico tipo 3 que permite al jugador obtener un material tipo 3 (superficie)
/// al mantener presionado el botón de interacción durante 1 segundo.
/// En la era prehistórica, este material es un adoquín.
/// </summary>
public class GenericObject3 : MonoBehaviour, IInteractable, IHoldInteractable
{    
    [Header("Configuración de objeto")]
    [SerializeField] private MaterialPrefabSO materialPrefabsSO; // Referencia al SO con los prefabs
    [SerializeField] private BridgeQuadrantSO.EraType era = BridgeQuadrantSO.EraType.Prehistoric;
    [SerializeField] private InteractPriority interactPriority = InteractPriority.Medium;
    [SerializeField] private GameObject shadow;

    [Header("Configuración de generación")]
    [SerializeField] private float tiempoPresionado = 1.0f; // Tiempo que hay que mantener presionado
    [SerializeField] private float tiempoRecarga = 2.0f; // Tiempo antes de poder generar otro material

    // Variables para controlar el estado
    private bool enRecarga = false;
    private bool enProceso = false;
    private float tiempoActual = 0f;
    private GameObject jugadorInteractuando = null;

    // Propiedad requerida por la interfaz IInteractable
    public InteractPriority InteractPriority => interactPriority;    

    private void Start()
    {
        // Verificar que tengamos las referencias necesarias
        if (materialPrefabsSO == null)
        {
            Debug.LogError("No se ha asignado el MaterialPrefabSO en " + gameObject.name);
        }

        shadow.SetActive(false);
    }

    private void Update()
    {
        // Si estamos en proceso de generar el material
        if (enProceso && jugadorInteractuando != null)
        {
            tiempoActual += Time.deltaTime;

            // Si se completa el tiempo requerido
            if (tiempoActual >= tiempoPresionado)
            {
                EntregarMaterial();
                ResetearProceso();
                StartCoroutine(Recargar());
            }

            // Aquí podrías añadir efectos visuales o sonidos que indiquen el progreso
            // Por ejemplo, una barra de progreso o un efecto de partículas que aumenta
        }
    }

    // Método llamado cuando un jugador interactúa con este objeto
    public void Interact(GameObject interactor)
    {
        if (enRecarga)
        {
            Debug.Log("Objeto en recarga, espera un momento.");
            return;
        }

        PlayerObjectHolder playerObjectHolder = interactor.GetComponent<PlayerObjectHolder>();

        if (playerObjectHolder != null)
        {
            // Iniciamos el proceso de mantener presionado
            if (!enProceso)
            {
                IniciarProceso(interactor);
                Debug.Log("Mantén presionado para obtener el material tipo 3 (superficie).");
            }
        }
        else
        {
            Debug.Log("El interactor no tiene el componente PlayerObjectHolder.");
        }
    }

    // Método llamado cuando el jugador suelta el botón de interacción
    public void DetenerInteraccion()
    {
        if (enProceso)
        {
            ResetearProceso();
            Debug.Log("Proceso cancelado. Debes mantener presionado el botón.");
        }
    }

    private void IniciarProceso(GameObject interactor)
    {
        enProceso = true;
        tiempoActual = 0f;
        jugadorInteractuando = interactor;

        // Aquí podrías iniciar efectos visuales o sonidos
    }

    private void ResetearProceso()
    {
        enProceso = false;
        tiempoActual = 0f;
        jugadorInteractuando = null;

        // Detener efectos visuales o sonidos
    }    

    private void EntregarMaterial()
    {
        if (materialPrefabsSO == null || jugadorInteractuando == null)
        {
            Debug.LogError("Falta MaterialPrefabSO o jugador para entregar material.");
            return;
        }

        // Obtener el prefab del material tipo 3 para la era actual
        GameObject materialPrefab = materialPrefabsSO.GetMaterialPrefab(3, era);

        if (materialPrefab == null)
        {
            Debug.LogError($"No se encontró prefab para material tipo 3 de la era {era}.");
            return;
        }

        PlayerObjectHolder playerObjectHolder = jugadorInteractuando.GetComponent<PlayerObjectHolder>();

        if (playerObjectHolder != null)
        {
            if (playerObjectHolder.HasObjectInHand())
            {
                Debug.Log("Jugador ya sostiene un objeto. Intercambiando objetos.");
            }

            // Generar una nueva instancia del material de superficie en la escena
            GameObject nuevoMaterial = Instantiate(materialPrefab, transform.position + Vector3.up * 0.5f, transform.rotation);

            // Configurar el material generado
            ConfigurarMaterialGenerado(nuevoMaterial);

            // Lógica para asignar el UIIndex al nuevo material, igual que GenericObject1
            UIIndexSetter sourceIndexSetter = GetComponent<UIIndexSetter>();
            int indexToAssign = sourceIndexSetter != null ? sourceIndexSetter.UIIndex : -1;

            UIIndexSetter uiIndexSetter = nuevoMaterial.GetComponent<UIIndexSetter>();
            if (uiIndexSetter == null)
            {
                uiIndexSetter = nuevoMaterial.AddComponent<UIIndexSetter>();
            }
            uiIndexSetter.SetUIIndex(indexToAssign);

            // Hacer que el jugador recoja la instancia recién creada
            playerObjectHolder.PickUpExistingInstance(nuevoMaterial);
            Debug.Log("Material tipo 3 (superficie) entregado con éxito.");

            // Opcional: Reproducir sonido o efecto visual
            ProducirEfectos();
        }
    }

    private void ConfigurarMaterialGenerado(GameObject material)
    {
        // Configurar el material generado como material de tipo superficie (nuevo tipo 3) de la era correspondiente
        BridgeMaterialInfo materialInfo = material.GetComponent<BridgeMaterialInfo>();
        if (materialInfo == null)
        {
            materialInfo = material.AddComponent<BridgeMaterialInfo>();
        }

        materialInfo.layerIndex = 2; // Tipo superficie corresponde a la capa superior (índice 2)
        materialInfo.era = era;
        materialInfo.materialType = BridgeQuadrantSO.MaterialType.Stone; // Superficie usa piedra/adoquín

        material.tag = "BridgeLayer2";

        Debug.Log($"Material superficie generado configurado: Era {era}, Capa 2, Tipo Stone");
    }

    private IEnumerator Recargar()
    {
        enRecarga = true;

        // TODO: Aquí puedes añadir una animación o cambio visual que indique la recarga

        yield return new WaitForSeconds(tiempoRecarga);

        enRecarga = false;
    }

    private void ProducirEfectos()
    {
        // TODO: Reproducir efectos visuales o sonidos
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Objeto genérico tipo 3 que permite al jugador obtener un material tipo 3 (superficie)
/// al mantener presionado el botón de interacción durante 1 segundo.
/// En la era prehistórica, este material es un adoquín.
/// </summary>
public class GenericObject3 : MonoBehaviour, IInteractable, IHoldInteractable
{    
    [Header("Configuración de objeto")]
    [SerializeField] private MaterialPrefabSO materialPrefabsSO; // Referencia al SO con los prefabs
    [SerializeField] private BridgeQuadrantSO.EraType era = BridgeQuadrantSO.EraType.Prehistoric;
    [SerializeField] private InteractPriority interactPriority = InteractPriority.Medium;
    [SerializeField] private GameObject shadow;

    [Header("Configuración de generación")]
    [SerializeField] private float tiempoPresionado = 1.0f; // Tiempo que hay que mantener presionado
    [SerializeField] private float tiempoRecarga = 2.0f; // Tiempo antes de poder generar otro material

    // Variables para controlar el estado
    private bool enRecarga = false;
    private bool enProceso = false;
    private float tiempoActual = 0f;
    private GameObject jugadorInteractuando = null;

    // Propiedad requerida por la interfaz IInteractable
    public InteractPriority InteractPriority => interactPriority;    

    private void Start()
    {
        // Verificar que tengamos las referencias necesarias
        if (materialPrefabsSO == null)
        {
            Debug.LogError("No se ha asignado el MaterialPrefabSO en " + gameObject.name);
        }

        shadow.SetActive(false);
    }

    private void Update()
    {
        // Si estamos en proceso de generar el material
        if (enProceso && jugadorInteractuando != null)
        {
            tiempoActual += Time.deltaTime;

            // Si se completa el tiempo requerido
            if (tiempoActual >= tiempoPresionado)
            {
                EntregarMaterial();
                ResetearProceso();
                StartCoroutine(Recargar());
            }

            // Aquí podrías añadir efectos visuales o sonidos que indiquen el progreso
            // Por ejemplo, una barra de progreso o un efecto de partículas que aumenta
        }
    }

    // Método llamado cuando un jugador interactúa con este objeto
    public void Interact(GameObject interactor)
    {
        if (enRecarga)
        {
            Debug.Log("Objeto en recarga, espera un momento.");
            return;
        }

        PlayerObjectHolder playerObjectHolder = interactor.GetComponent<PlayerObjectHolder>();

        if (playerObjectHolder != null)
        {
            // Iniciamos el proceso de mantener presionado
            if (!enProceso)
            {
                IniciarProceso(interactor);
                Debug.Log("Mantén presionado para obtener el material tipo 3 (superficie).");
            }
        }
        else
        {
            Debug.Log("El interactor no tiene el componente PlayerObjectHolder.");
        }
    }

    // Método llamado cuando el jugador suelta el botón de interacción
    public void DetenerInteraccion()
    {
        if (enProceso)
        {
            ResetearProceso();
            Debug.Log("Proceso cancelado. Debes mantener presionado el botón.");
        }
    }

    private void IniciarProceso(GameObject interactor)
    {
        enProceso = true;
        tiempoActual = 0f;
        jugadorInteractuando = interactor;

        // Aquí podrías iniciar efectos visuales o sonidos
    }

    private void ResetearProceso()
    {
        enProceso = false;
        tiempoActual = 0f;
        jugadorInteractuando = null;

        // Detener efectos visuales o sonidos
    }    

    private void EntregarMaterial()
    {
        if (materialPrefabsSO == null || jugadorInteractuando == null)
        {
            Debug.LogError("Falta MaterialPrefabSO o jugador para entregar material.");
            return;
        }

        // Obtener el prefab del material tipo 3 para la era actual
        GameObject materialPrefab = materialPrefabsSO.GetMaterialPrefab(3, era);

        if (materialPrefab == null)
        {
            Debug.LogError($"No se encontró prefab para material tipo 3 de la era {era}.");
            return;
        }

        PlayerObjectHolder playerObjectHolder = jugadorInteractuando.GetComponent<PlayerObjectHolder>();

        if (playerObjectHolder != null)
        {
            if (playerObjectHolder.HasObjectInHand())
            {
                Debug.Log("Jugador ya sostiene un objeto. Intercambiando objetos.");
            }

            // Generar una nueva instancia del material de superficie en la escena
            GameObject nuevoMaterial = Instantiate(materialPrefab, transform.position + Vector3.up * 0.5f, transform.rotation);

            // Configurar el material generado
            ConfigurarMaterialGenerado(nuevoMaterial);

            // Lógica para asignar el UIIndex al nuevo material, igual que GenericObject1
            UIIndexSetter sourceIndexSetter = GetComponent<UIIndexSetter>();
            int indexToAssign = sourceIndexSetter != null ? sourceIndexSetter.UIIndex : -1;

            UIIndexSetter uiIndexSetter = nuevoMaterial.GetComponent<UIIndexSetter>();
            if (uiIndexSetter == null)
            {
                uiIndexSetter = nuevoMaterial.AddComponent<UIIndexSetter>();
            }
            uiIndexSetter.SetUIIndex(indexToAssign);

            // Hacer que el jugador recoja la instancia recién creada
            playerObjectHolder.PickUpExistingInstance(nuevoMaterial);
            Debug.Log("Material tipo 3 (superficie) entregado con éxito.");

            // Opcional: Reproducir sonido o efecto visual
            ProducirEfectos();
        }
    }

    private void ConfigurarMaterialGenerado(GameObject material)
    {
        // Configurar el material generado como material de tipo superficie (nuevo tipo 3) de la era correspondiente
        BridgeMaterialInfo materialInfo = material.GetComponent<BridgeMaterialInfo>();
        if (materialInfo == null)
        {
            materialInfo = material.AddComponent<BridgeMaterialInfo>();
        }

        materialInfo.layerIndex = 2; // Tipo superficie corresponde a la capa superior (índice 2)
        materialInfo.era = era;
        materialInfo.materialType = BridgeQuadrantSO.MaterialType.Stone; // Superficie usa piedra/adoquín

        material.tag = "BridgeLayer2";

        Debug.Log($"Material superficie generado configurado: Era {era}, Capa 2, Tipo Stone");
    }

    private IEnumerator Recargar()
    {
        enRecarga = true;

        // TODO: Aquí puedes añadir una animación o cambio visual que indique la recarga

        yield return new WaitForSeconds(tiempoRecarga);

        enRecarga = false;
    }

    private void ProducirEfectos()
    {
        // TODO: Reproducir efectos visuales o sonidos
    }
}
